const fs = require('fs');
const path = require('path');
const dotenv = require('dotenv');

// Load environment variables from .env.test
const envConfig = dotenv.parse(fs.readFileSync(path.resolve('.env.test')));

// Extract secret names (keys) from .env.test
const SECRET_NAMES = Object.keys(envConfig);

// Mock AWS.SecretsManager for demonstration
// In real use, you'd require('aws-sdk') and instantiate AWS.SecretsManager
const mockAwsSecretsManager = {
  getSecretValue(params, callback) {
    // Simulate fetching from AWS
    // In reality, this would make an actual AWS API call
    const awsSecrets = {
      // These would be stored in AWS, not here
    };

    // Simulate async behavior
    setImmediate(() => {
      const secret = awsSecrets[params.SecretId];
      if (secret) {
        callback(null, { SecretString: secret });
      } else {
        const error = { code: 'ResourceNotFoundException' };
        callback(error, null);
      }
    });
  }
};

/**
 * Get a secret by name
 * @param {string} name - The name/key of the secret
 * @returns {Promise<string>} - The secret value
 */
async function getSecret(name) {
  if (!SECRET_NAMES.includes(name)) {
    throw new Error(`Secret '${name}' is not defined in .env.test`);
  }

  // Try AWS Secrets Manager first
  try {
    const result = await new Promise((resolve, reject) => {
      mockAwsSecretsManager.getSecretValue({ SecretId: name }, (err, data) => {
        if (err) {
          reject(err);
        } else {
          resolve(data);
        }
      });
    });

    return result.SecretString;
  } catch (error) {
    if (error.code === 'ResourceNotFoundException') {
      console.warn(`Secret '${name}' not found in AWS Secrets Manager, using local fallback`);
      // Fallback to .env.test value
      return envConfig[name];
    }
    throw error;
  }
}

module.exports = { getSecret, SECRET_NAMES };

