// secrets.js
// Module for secure secret retrieval with AWS Secrets Manager and local .env fallback

const AWS = require('aws-sdk');
const dotenv = require('dotenv');

// Load .env.test to get secret names (values ignored in production)
const envConfig = dotenv.parse(require('fs').readFileSync('.env.test', 'utf8'));
const SECRET_NAMES = Object.keys(envConfig);

class SecretsManager {
  constructor() {
    this.secretsCache = new Map();
    this.isLocal = process.env.NODE_ENV !== 'production';

    if (!this.isLocal) {
      this.secretsManager = new AWS.SecretsManager({ region: process.env.AWS_REGION });
    }
  }

  async getSecret(name) {
    // Validate requested secret is in allowed list
    if (!SECRET_NAMES.includes(name)) {
      throw new Error(`Access denied: '${name}' is not a configured secret`);
    }

    // Return from cache if available
    if (this.secretsCache.has(name)) {
      return this.secretsCache.get(name);
    }

    let value;

    if (this.isLocal) {
      // Local development: load from .env.test
      const dotenv = require('dotenv');
      const env = dotenv.parse(require('fs').readFileSync('.env.test', 'utf8'));
      value = env[name];

      if (!value) {
        throw new Error(`Local secret '${name}' not found in .env.test`);
      }
    } else {
      // Production: fetch from AWS Secrets Manager
      try {
        const data = await this.secretsManager.getSecretValue({ SecretId: name }).promise();
        const secrets = JSON.parse(data.SecretString);
        value = secrets[name];

        if (value === undefined) {
          throw new Error(`Secret '${name}' not found in AWS Secrets Manager response`);
        }
      } catch (error) {
        throw new Error(`Failed to retrieve secret '${name}': ${error.message}`);
      }
    }

    // Cache the value
    this.secretsCache.set(name, value);
    return value;
  }
}

// Create singleton instance
const secrets = new SecretsManager();

// Convenience function for direct use
const getSecret = (name) => secrets.getSecret(name);

module.exports = { getSecret, secrets, SECRET_NAMES };

