require('dotenv').config({ path: '.env.test' });

const AWS = require('aws-sdk');

// Initialize AWS.SecretsManager
const secretsManager = new AWS.SecretsManager({
  region: process.env.AWS_REGION || 'us-east-1',
});

// Parse .env.test to get list of required secrets
function getRequiredSecretNames() {
  const envContent = require('fs').readFileSync('.env.test', 'utf8');
  const secretNames = [];
  envContent.split('\n').forEach(line => {
    if (line.trim() && !line.startsWith('#')) {
      const match = line.match(/^([^=]+)=/);
      if (match) {
        secretNames.push(match[1].trim());
      }
    }
  });
  return secretNames;
}

const requiredSecrets = getRequiredSecretNames();

// Cache for fetched secrets
const secretCache = {};

/**
 * Get a secret value by name
 * @param {string} name - The name of the secret
 * @returns {Promise<string>} - The secret value
 */
async function getSecret(name) {
  // Return from cache if available
  if (secretCache[name]) {
    return secretCache[name];
  }

  // Try to get from process.env (local development)
  if (process.env[name]) {
    secretCache[name] = process.env[name];
    return process.env[name];
  }

  // Fetch from AWS Secrets Manager
  try {
    const data = await secretsManager.getSecretValue({ SecretId: name }).promise();
    let secretValue;

    if (data.SecretString) {
      secretValue = data.SecretString;
    } else {
      // For binary secrets
      secretValue = Buffer.from(data.SecretBinary, 'base64').toString('ascii');
    }

    secretCache[name] = secretValue;
    return secretValue;
  } catch (error) {
    console.warn(`Failed to fetch secret '${name}' from AWS Secrets Manager:`, error.message);

    // If we're in development and secret doesn't exist in AWS, check .env.test
    if (requiredSecrets.includes(name)) {
      console.log(`Falling back to .env.test for secret '${name}'`);
      const envContent = require('fs').readFileSync('.env.test', 'utf8');
      const regex = new RegExp(^${name}=([^\n]+)$, 'm');
      const match = envContent.match(regex);
      if (match) {
        const value = match[1].trim();
        secretCache[name] = value;
        return value;
      }
    }

    throw new Error(`Secret '${name}' not found`);
  }
}

module.exports = { getSecret };

