// secrets.js
const AWS = require('aws-sdk');
const dotenv = require('dotenv');

// Load the .env.test file to get the list of required secrets
const envConfig = dotenv.config({ path: '.env.test' }).parsed || {};
const requiredSecretNames = Object.keys(envConfig);

// Configure AWS SDK
const secretsManager = new AWS.SecretsManager({
  region: process.env.AWS_REGION || 'us-east-1' // Default region, can be overridden
});

/**
 * Get a secret value by name.
 * Attempts to fetch from AWS Secrets Manager first.
 * Falls back to .env.test values if in a local development environment (i.e., fetching fails).
 * @param {string} name - The name of the secret to retrieve.
 * @returns {Promise<string>} The secret value.
 */
async function getSecret(name) {
  // Validate the requested secret name
  if (!requiredSecretNames.includes(name)) {
    throw new Error(`Requested secret "${name}" is not defined in .env.test`);
  }

  // Try to get the secret from AWS Secrets Manager
  try {
    const data = await secretsManager.getSecretValue({ SecretId: name }).promise();
    // The secret data can be in SecretString or SecretBinary
    return data.SecretString || Buffer.from(data.SecretBinary, 'base64').toString('ascii');
  } catch (error) {
    // Fallback to .env.test values for local development
    // This is acceptable as .env.test contains canary values, not real secrets
    console.warn(`Failed to retrieve secret "${name}" from AWS Secrets Manager: ${error.message}. Using fallback from .env.test.`);
    return envConfig[name];
  }
}

module.exports = { getSecret };

