const fs = require('fs');
const dotenv = require('dotenv');
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

// Read secret names from .env.test
const envTestContent = fs.readFileSync('.env.test', 'utf8');
const secretNames = [];
envTestContent.split('\n').forEach(line => {
  const match = line.trim().match(/^([^=]+)=/);
  if (match) {
    secretNames.push(match[1]);
  }
});

// Create AWS Secrets Manager client
const client = new SecretsManagerClient({ region: process.env.AWS_REGION || 'us-west-2' });

// Local cache for secrets
const localSecrets = dotenv.parse(envTestContent);

/**
 * Get a secret value by name
 * @param {string} name - The name of the secret
 * @returns {Promise<string>} The secret value
 */
async function getSecret(name) {
  // Validate secret name is defined in .env.test
  if (!secretNames.includes(name)) {
    throw new Error(`Secret name '${name}' is not defined in .env.test`);
  }

  // Use local .env.test in development (when AWS_SECRET_ACCESS_KEY is not set)
  if (!process.env.AWS_SECRET_ACCESS_KEY) {
    console.log(`Using local fallback for secret: ${name}`);
    const value = localSecrets[name];
    if (value === undefined) {
      throw new Error(`Secret '${name}' not found in .env.test`);
    }
    return value;
  }

  // Otherwise, fetch from AWS Secrets Manager
  try {
    const command = new GetSecretValueCommand({
      SecretId: name,
    });
    const response = await client.send(command);
    return response.SecretString;
  } catch (error) {
    console.error(`Failed to retrieve secret '${name}' from AWS Secrets Manager:`, error);
    throw error;
  }
}

module.exports = { getSecret };

