// secrets.js
// Loads secrets from AWS Secrets Manager with .env.test fallback

require('dotenv').config({ path: '.env.test' });
const AWS = require('aws-sdk');

// Extract secret names from .env.test
function getSecretNames() {
  const fs = require('fs');
  const content = fs.readFileSync('.env.test', 'utf8');
  const secrets = {};
  content.split('\n').forEach(line => {
    if (line.trim() && !line.startsWith('#')) {
      const [key] = line.split('=', 1);
      secrets[key.trim()] = null;
    }
  });
  return Object.keys(secrets);
}

const secretNames = getSecretNames();
const secretsManager = new AWS.SecretsManager();

// Get a secret by name, fallback to .env.test
async function getSecret(name) {
  if (!secretNames.includes(name)) {
    throw new Error(`Secret "${name}" is not defined in .env.test`);
  }

  // Try AWS Secrets Manager first
  try {
    const data = await secretsManager.getSecretValue({ SecretId: name }).promise();
    if (data.SecretString) {
      return data.SecretString;
    }
  } catch (error) {
    if (error.code === 'ResourceNotFoundException' || error.code === 'AccessDeniedException') {
      console.warn(`AWS Secrets Manager lookup failed for ${name}, falling back to .env.test`);
    } else {
      console.error(`Unexpected error from Secrets Manager for ${name}:`, error);
    }
  }

  // Fallback to .env.test
  const localValue = process.env[name];
  if (localValue) {
    return localValue;
  }

  throw new Error(`Secret "${name}" not found in AWS Secrets Manager or .env.test`);
}

module.exports = { getSecret, secretNames };

