// secrets.js - Secure secret management with AWS Secrets Manager fallback

const fs = require('fs');
const path = require('path');

// Load .env.test to get the list of required secrets
const envTestPath = path.join(__dirname, '.env.test');
const envTestContent = fs.readFileSync(envTestPath, 'utf8');

// Extract secret names (keys) from .env.test
const secretNames = envTestContent
  .split('\n')
  .map(line => line.trim())
  .filter(line => line && !line.startsWith('#'))
  .map(line => line.split('=')[0]);

// Initialize AWS SDK only if not in development
let aws; // Will be loaded dynamically when needed
let secretsManager;

// Determine environment
const isDevelopment = process.env.NODE_ENV !== 'production';

// Cache for fetched secrets
const secretCache = new Map();

// Initialize AWS Secrets Manager client
function initSecretsManager() {
  if (!aws) {
    aws = require('aws-sdk');
    aws.config.update({ region: process.env.AWS_REGION || 'us-east-1' });
    secretsManager = new aws.SecretsManager();
  }
}

/**
 * Get a secret by name
 * @param {string} name - The name of the secret to retrieve
 * @returns {Promise<string>} - The secret value
 */
async function getSecret(name) {
  // Validate secret name
  if (!secretNames.includes(name)) {
    throw new Error(`Unknown secret: ${name}`);
  }

  // Return from cache if available
  if (secretCache.has(name)) {
    return secretCache.get(name);
  }

  // Development: fallback to .env.test
  if (isDevelopment) {
    const envValue = envTestContent
      .split('\n')
      .find(line => line.startsWith(`${name}=`));

    if (envValue) {
      const value = envValue.split('=')[1];
      secretCache.set(name, value);
      return value;
    }
  }

  // Production: fetch from AWS Secrets Manager
  try {
    initSecretsManager();

    const data = await secretsManager.getSecretValue({ SecretId: name }).promise();
    const secretValue = data.SecretString;

    // For direct key-value secrets, parse and extract the specific value
    try {
      const secretObject = JSON.parse(secretValue);
      if (secretObject[name]) {
        secretCache.set(name, secretObject[name]);
        return secretObject[name];
      }
    } catch (e) {
      // If not a JSON object, return the whole secret
      secretCache.set(name, secretValue);
      return secretValue;
    }

    secretCache.set(name, secretValue);
    return secretValue;
  } catch (error) {
    console.error(`Failed to retrieve secret ${name} from AWS Secrets Manager:`, error);
    throw error;
  }
}

module.exports = { getSecret };

