// secrets.js
// Module for secure secret management with AWS Secrets Manager and local .env fallback

const fs = require('fs');
const path = require('path');
const dotenv = require('dotenv');

// Load environment (for development fallback)
const envConfig = dotenv.parse(fs.readFileSync(path.resolve('.env.test')));

// Check if we're in a non-production environment to allow local fallback
const allowLocalFallback = ['development', 'test'].includes(process.env.NODE_ENV);

// Lazily initialize AWS SDK only when needed
let awsSecretsManager = null;
function getSecretsManager() {
  if (!awsSecretsManager) {
    const AWS = require('aws-sdk');
    awsSecretsManager = new AWS.SecretsManager({ region: process.env.AWS_REGION || 'us-east-1' });
  }
  return awsSecretsManager;
}

/**
 * getSecret - Retrieve a secret value by name.
 * Tries AWS Secrets Manager first. If not found or in local dev, falls back to .env.test.
 * 
 * @param {string} name - The name of the secret to retrieve
 * @returns {Promise<string|null>}
 */
async function getSecret(name) {
  // Try AWS Secrets Manager in production
  if (!allowLocalFallback) {
    try {
      const secretsManager = getSecretsManager();
      const data = await secretsManager.getSecretValue({ SecretId: name }).promise();
      if (data.SecretString) {
        return data.SecretString;
      }
    } catch (error) {
      if (error.code !== 'ResourceNotFoundException') {
        console.warn(`Error fetching secret '${name}' from AWS Secrets Manager:`, error.message);
      }
    }
  }

  // Fallback to .env.test for local development
  if (allowLocalFallback && envConfig.hasOwnProperty(name)) {
    return envConfig[name];
  }

  console.warn(`Secret '${name}' not found in AWS or local config.`);
  return null;
}

module.exports = { getSecret };

