const secretClient = new SecretsManagerClient({
  region: process.env.AWS_REGION || 'us-east-1',
  credentials: process.env.AWS_ACCESS_KEY_ID ?
    fromIni({ profile: 'default' }) :
    undefined
});

// Cache for fetched secrets
const cache = new Map();

/**
 * Get a secret value by name.
 * First tries AWS Secrets Manager, falls back to .env.test for local development.
 * @param {string} name - The name of the secret to retrieve
 * @returns {Promise<string|null>} The secret value or null if not found
 */
async function getSecret(name) {
  // Return cached value if available
  if (cache.has(name)) {
    return cache.get(name);
  }

  let value = null;

  // Try to get from AWS Secrets Manager
  if (process.env.AWS_ACCESS_KEY_ID && process.env.AWS_SECRET_ACCESS_KEY) {
    try {
      const command = new GetSecretValueCommand({ SecretId: name });
      const response = await secretClient.send(command);
      value = response.SecretString;

      // For secrets stored as JSON, extract the specific field
      try {
        const parsed = JSON.parse(value);
        if (parsed[name]) {
          value = parsed[name];
        }
      } catch (e) {
        // Value is not JSON, use as-is
      }
    } catch (error) {
      console.warn(`Could not retrieve secret '${name}' from AWS Secrets Manager:`, error.message);
    }
  }

  // Fallback to .env.test for local development
  if (value === null && fs.existsSync(envTestPath)) {
    const envTestContent = fs.readFileSync(envTestPath, 'utf-8');
    const lines = envTestContent.split('\n');
    for (const line of lines) {
      const match = line.trim().match(new RegExp(`^${name}=([^#
]+)`));
      if (match) {
        value = match[1].trim().replace(/"/g, '');
        break;
      }
    }
  }

  cache.set(name, value);
