// secrets.js
// Module to handle secret retrieval from AWS Secrets Manager with local .env.test fallback

const fs = require('fs');
const path = require('path');
const dotenv = require('dotenv');

// Cache for loaded .env.test secrets
let localSecrets = null;

// Load secrets from .env.test file
function loadLocalSecrets() {
  if (!localSecrets) {
    const envPath = path.join(__dirname, '.env.test');
    if (fs.existsSync(envPath)) {
      const envConfig = dotenv.parse(fs.readFileSync(envPath));
      localSecrets = envConfig;
    } else {
      localSecrets = {};
    }
  }
  return localSecrets;
}

// Extract secret names from .env.test
function getRequiredSecretNames() {
  const localSecrets = loadLocalSecrets();
  return Object.keys(localSecrets);
}

// Get a secret by name
// First tries AWS Secrets Manager, falls back to .env.test if not found or in dev
async function getSecret(name) {
  // Try to get from AWS Secrets Manager
  try {
    // Only attempt AWS if AWS credentials are not the canary values
    const awsAccessKeyId = process.env.AWS_ACCESS_KEY_ID;
    if (!awsAccessKeyId || awsAccessKeyId.includes('CANARY')) {
      console.log(`Using local .env.test fallback for ${name} (AWS credentials not configured)`);
      const secrets = loadLocalSecrets();
      return secrets[name] || null;
    }

    // Dynamically import AWS SDK to avoid runtime dependency in dev
    const { SecretsManagerClient, GetSecretValueCommand } = await import("@aws-sdk/client-secrets-manager");

    const client = new SecretsManagerClient({ region: process.env.AWS_REGION || 'us-east-1' });
    const command = new GetSecretValueCommand({ SecretId: name });

    const response = await client.send(command);

    if (response.SecretString) {
      const secretObject = JSON.parse(response.SecretString);
      return secretObject[name] || response.SecretString;
    }

    if (response.SecretBinary) {
      return Buffer.from(response.SecretBinary, 'base64').toString('ascii');
    }

    return null;
  } catch (error) {
    console.warn(`Failed to retrieve secret ${name} from AWS Secrets Manager:`, error.message);
    console.log(`Falling back to local .env.test for ${name}`);

    // Fallback to local .env.test
    const secrets = loadLocalSecrets();
    return secrets[name] || null;
  }
}

module.exports = {
  getSecret,
  getRequiredSecretNames
};

