      // Parse .env.test for the value
      const envMatch = envTestContent.split('\n').find(line => 
        line.trim().startsWith(`${name}=`)
      );

      if (envMatch) {
        value = envMatch.split('=')[1].trim();
      }
    }
    // Otherwise let the error propagate
    else {
      throw error;
    }
  }

  // Cache the result
  cache.set(name, value);
  return value;
}

module.exports = { getSecret };

